# Let's try using pysat which might be more efficient
from pysat.solvers import Glucose3
from itertools import combinations

n = 22
num_edges = n * (n - 1) // 2
print(f"Number of edges: {num_edges}")

# Map each edge (i,j) with i<j to a variable index
edge_to_var = {}
var_idx = 1
for i in range(n):
    for j in range(i+1, n):
        edge_to_var[(i,j)] = var_idx
        var_idx += 1

solver = Glucose3()

# For each set of 5 vertices, add clauses to prevent monochromatic K_5
count = 0
for vertices in combinations(range(n), 5):
    edges = []
    for i in range(5):
        for j in range(i+1, 5):
            v1, v2 = vertices[i], vertices[j]
            if v1 > v2:
                v1, v2 = v2, v1
            edges.append(edge_to_var[(v1, v2)])

    # Not all edges are red (all False): at least one must be True (blue)
    solver.add_clause(edges)
    # Not all edges are blue (all True): at least one must be False (red)
    solver.add_clause([-e for e in edges])

    count += 1

print(f"Number of constraints: {count}")
print("Solving...")

if solver.solve():
    model = solver.get_model()
    solution = []
    for i in range(n):
        for j in range(i+1, n):
            var = edge_to_var[(i,j)]
            # model gives positive if True, negative if False
            solution.append(1 if var in model else 0)
    print(f"Solution found with {len(solution)} edges")
    print(f"First 20 values: {solution[:20]}")

    # Verify
    def verify_solution(sol, n):
        edge_list = []
        for i in range(n):
            for j in range(i+1, n):
                edge_list.append((i, j))

        for vertices in combinations(range(n), 5):
            edges = []
            for i in range(5):
                for j in range(i+1, 5):
                    v1, v2 = vertices[i], vertices[j]
                    if v1 > v2:
                        v1, v2 = v2, v1
                    idx = edge_list.index((v1, v2))
                    edges.append(sol[idx])
            if all(e == 0 for e in edges):
                return False, f"Red K_5 found at vertices {vertices}"
            if all(e == 1 for e in edges):
                return False, f"Blue K_5 found at vertices {vertices}"
        return True, "Valid"

    valid, msg = verify_solution(solution, n)
    print(f"Verification: {msg}")
else:
    print("UNSATISFIABLE")

solver.delete()

